	/**
	 * Get the country states if they exist.
	 *
	 * @param string $country  The country guid
	 *
	 * @return array
	 * @since 5.0.2
	 */
	public function getCountryStates(string $country): array
	{
		if (Super___9c513baf_b279_43fd_ae29_a585c8cbc4f0___Power::valid($country))
		{
			try
			{
				$result = Super___9d76b8dc_3883_4755_b11c_131d19ca8a53___Power::_('Data.Items')->table('state')->get([$country], 'country');
			}
			catch (\Exception $error)
			{
				return ['error' => $error->getMessage()];
			}

			if ($result !== null)
			{
				$states = array_map(function ($state) {
					return (object) ['value' => $state->guid, 'text' => $state->name];
				}, $result);

				return ['data' => $states];
			}
		}

		return ['error' => Text::_('The country states could not be found')];
	}

